const revokeAllSessionsForUser = `-- name: RevokeAllSessionsForUser :many
UPDATE auth.sessions SET revoked_at = NOW()
WHERE user_id = $1 AND revoked_at IS NULL
  AND expires_at > NOW() AND last_seen_at + idle_timeout > NOW()
RETURNING id, organization_id
`

type RevokeAllSessionsForUserRow struct {
	ID             uuid.UUID
	OrganizationID *uuid.UUID
}

// RevokeAllSessionsForUser ends every live session of the user, the caller's
// own included. Ending a session is what kills its refresh tokens. A session
// past its maximum age or idle timeout has already ended and is left as expired.
func (q *Queries) RevokeAllSessionsForUser(ctx context.Context, userID uuid.UUID) ([]RevokeAllSessionsForUserRow, error) {
	rows, err := q.db.Query(ctx, revokeAllSessionsForUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RevokeAllSessionsForUserRow{}
	for rows.Next() {
		var i RevokeAllSessionsForUserRow
		if err := rows.Scan(&i.ID, &i.OrganizationID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const revokeAppGrantsForLoginSession = `-- name: RevokeAppGrantsForLoginSession :one
WITH ended AS (
    UPDATE auth.oidc_refresh_tokens SET revoked_at = NOW()
    WHERE login_session_id = $1 AND revoked_at IS NULL
    RETURNING used_at, expires_at
)
SELECT COUNT(*)::bigint AS touched,
       COUNT(*) FILTER (WHERE used_at IS NULL AND expires_at > NOW())::bigint AS live
FROM ended
`

type RevokeAppGrantsForLoginSessionRow struct {
	Touched int64
	Live    int64
}

// RevokeAppGrantsForLoginSession ends the application grants the session
// started — every not-yet-revoked token in their chains, renewals included —
// and returns how many rows it touched and how many were the live head of a
// grant (the number of grants it ended), like RevokeAppGrantsForUser.
func (q *Queries) RevokeAppGrantsForLoginSession(ctx context.Context, loginSessionID *uuid.UUID) (RevokeAppGrantsForLoginSessionRow, error) {
	row := q.db.QueryRow(ctx, revokeAppGrantsForLoginSession, loginSessionID)
	var i RevokeAppGrantsForLoginSessionRow
	err := row.Scan(&i.Touched, &i.Live)
	return i, err
}

const revokeAppGrantsForUser = `-- name: RevokeAppGrantsForUser :one
WITH ended AS (
    UPDATE auth.oidc_refresh_tokens SET revoked_at = NOW()
    WHERE user_id = $1 AND revoked_at IS NULL
    RETURNING used_at, expires_at
)
SELECT COUNT(*)::bigint AS touched,
       COUNT(*) FILTER (WHERE used_at IS NULL AND expires_at > NOW())::bigint AS live
FROM ended
`

type RevokeAppGrantsForUserRow struct {
	Touched int64
	Live    int64
}

// RevokeAppGrantsForUser ends every application grant (OIDC refresh-token
// chain) the user holds, for every application. It marks every not-yet-revoked
// token of the user revoked — rotated-away ones too, so presenting an old one
// later reads as revoked rather than as theft — and returns how many rows it
// touched (touched) and how many were the live head of a grant (live: unused
// and unexpired), which is the number of grants it ended.
func (q *Queries) RevokeAppGrantsForUser(ctx context.Context, userID uuid.UUID) (RevokeAppGrantsForUserRow, error) {
	row := q.db.QueryRow(ctx, revokeAppGrantsForUser, userID)
	var i RevokeAppGrantsForUserRow
	err := row.Scan(&i.Touched, &i.Live)
	return i, err
}

const revokeOtherSessionsForUser = `-- name: RevokeOtherSessionsForUser :many
UPDATE auth.sessions SET revoked_at = NOW()
WHERE user_id = $1 AND id <> $2 AND revoked_at IS NULL
  AND expires_at > NOW() AND last_seen_at + idle_timeout > NOW()
RETURNING id, organization_id
`

type RevokeOtherSessionsForUserParams struct {
	UserID        uuid.UUID
	KeepSessionID uuid.UUID
}

type RevokeOtherSessionsForUserRow struct {
	ID             uuid.UUID
	OrganizationID *uuid.UUID
}

// RevokeOtherSessionsForUser revokes all of a user's active sessions except the
// one they're currently on — used after a password change/set so a compromised
// session can't survive the credential rotation. A session past its maximum age
// or idle timeout has already ended and is left as expired.
func (q *Queries) RevokeOtherSessionsForUser(ctx context.Context, arg RevokeOtherSessionsForUserParams) ([]RevokeOtherSessionsForUserRow, error) {
	rows, err := q.db.Query(ctx, revokeOtherSessionsForUser, arg.UserID, arg.KeepSessionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RevokeOtherSessionsForUserRow{}
	for rows.Next() {
		var i RevokeOtherSessionsForUserRow
		if err := rows.Scan(&i.ID, &i.OrganizationID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

